select title.production_year, title.md5sum from movie_link, title where movie_link.link_type_id = 4 AND title.title >= 'Historia de un río' AND title.imdb_index > 'I' AND title.series_years > '2005-2009' AND movie_link.linked_movie_id > 1394139 AND title.imdb_index = 'I' AND title.phonetic_code > 'T6216'
SELECT name.imdb_index, cast_info.movie_id, role_type.id, COUNT(name.id) FROM name JOIN cast_info ON cast_info.person_id = name.id JOIN role_type ON role_type.id = cast_info.role_id WHERE name.id <= 2456285 AND cast_info.nr_order >= 69 AND name.surname_pcode = 'K252' GROUP BY name.imdb_index, cast_info.movie_id, role_type.id ORDER BY COUNT(name.id) DESC
select keyword.keyword, keyword.phonetic_code from movie_keyword JOIN keyword ON keyword.id = movie_keyword.keyword_id where movie_keyword.id >= 205842 AND keyword.id = 43184 AND keyword.id >= 86959 AND movie_keyword.movie_id = 1882109 order by keyword.keyword ASC, keyword.phonetic_code DESC
select info_type.id, company_name.name, movie_info_idx.movie_id, movie_companies.movie_id, movie_companies.company_type_id from info_type JOIN movie_info_idx ON movie_info_idx.info_type_id = info_type.id JOIN title ON title.id = movie_info_idx.movie_id JOIN movie_companies ON movie_companies.movie_id = title.id JOIN company_name ON company_name.id = movie_companies.company_id where title.id >= 2108925 AND title.episode_of_id >= 1079578 order by company_name.name ASC
