select movie_companies.company_type_id, company_type.kind, count(movie_companies.company_type_id), sum(movie_companies.movie_id), max(company_type.kind) from company_type, movie_companies where movie_companies.note < '(1979) (USA: Midwest) (theatrical) (dubbed)' AND movie_companies.id >= 541531 AND movie_companies.movie_id = 1688927 group by movie_companies.company_type_id, company_type.kind
