SELECT title.id, movie_companies.company_type_id, company_name.name FROM title JOIN movie_companies ON movie_companies.movie_id = title.id JOIN company_name ON company_name.id = movie_companies.company_id WHERE company_name.id >= 159463 AND title.episode_nr > 54 AND company_name.country_code > '[in]' ORDER BY company_name.name ASC, movie_companies.company_type_id ASC
SELECT company_name.country_code, movie_companies.company_type_id FROM movie_companies JOIN company_name ON company_name.id = movie_companies.company_id WHERE movie_companies.note <= '(2008) (Argentina) (DVD)' AND company_name.name = 'G.W. Films Limited' AND company_name.md5sum < 'b6dfd4e57fa5a8bc33331a657b78eb0a' AND movie_companies.company_id <> 4808 ORDER BY movie_companies.company_type_id ASC
