SELECT company_name.name_pcode_nf, company_type.id, movie_companies.company_id FROM company_name, movie_companies, company_type WHERE company_name.name_pcode_nf < 'U5162' AND company_name.name = 'Five International' AND movie_companies.company_type_id >= 1 AND company_name.country_code <= '[in]'
SELECT MIN(an.name) AS cool_actor_pseudonym, MIN(t.title) AS series_named_after_char FROM aka_name AS an, cast_info AS ci, company_name AS cn, keyword AS k, movie_companies AS mc, movie_keyword AS mk, name AS n, title AS t WHERE cn.country_code = '[us]' AND k.keyword = 'character-name-in-title' AND t.episode_nr >= 50 AND t.episode_nr < 100 AND an.person_id = n.id AND n.id = ci.person_id AND ci.movie_id = t.id AND t.id = mk.movie_id AND mk.keyword_id = k.id AND t.id = mc.movie_id AND mc.company_id = cn.id AND an.person_id = ci.person_id AND ci.movie_id = mc.movie_id AND ci.movie_id = mk.movie_id AND mc.movie_id = mk.movie_id
SELECT movie_link.movie_id, cast_info.note, title.kind_id, char_name.name_pcode_nf FROM char_name JOIN cast_info ON cast_info.person_role_id = char_name.id JOIN title ON title.id = cast_info.movie_id JOIN movie_link ON movie_link.movie_id = title.id WHERE cast_info.movie_id > 1336886 AND movie_link.id > 23398 AND movie_link.linked_movie_id > 1330291 AND movie_link.link_type_id >= 4
