select title.season_nr, title.production_year, movie_link.id, avg(movie_link.id), max(movie_link.movie_id) from link_type, movie_link, title where title.imdb_index <= 'II' AND link_type.link > 'edited into' AND movie_link.movie_id = 8087 group by movie_link.id, title.season_nr, title.production_year order by movie_link.id DESC
