select title.md5sum, movie_link.movie_id, movie_link.linked_movie_id, link_type.link from movie_keyword JOIN title ON title.id = movie_keyword.movie_id JOIN movie_link ON movie_link.movie_id = title.id JOIN link_type ON link_type.id = movie_link.link_type_id where movie_keyword.movie_id < 1644942 AND link_type.link >= 'spin off from' AND title.title >= 'Pericolo di vita' order by movie_link.movie_id ASC, title.md5sum DESC, link_type.link DESC, movie_link.linked_movie_id ASC
SELECT cast_info.role_id, name.id FROM name, cast_info WHERE name.id < 3785599 AND name.md5sum > '6206aa6679331c322cb1a4fb14215ea6' AND name.name = 'Kan, Wai-Yan' AND cast_info.nr_order >= 69 ORDER BY cast_info.role_id DESC
SELECT company_name.id, movie_companies.movie_id FROM movie_companies, company_name WHERE company_name.name_pcode_nf > 'U5162' AND movie_companies.note = '(2011) (Italy) (theatrical)' AND company_name.id >= 159463 AND company_name.country_code <> '[us]' AND movie_companies.company_id < 5197 AND company_name.name_pcode_sf > 'A3463' AND movie_companies.company_type_id < 1 ORDER BY movie_companies.movie_id DESC, company_name.id DESC
SELECT name.id, person_info.person_id, title.episode_of_id, cast_info.person_id, complete_cast.movie_id, comp_cast_type.kind FROM person_info JOIN name ON name.id = person_info.person_id JOIN cast_info ON cast_info.person_id = name.id JOIN title ON title.id = cast_info.movie_id JOIN complete_cast ON complete_cast.movie_id = title.id JOIN comp_cast_type ON comp_cast_type.id = complete_cast.status_id WHERE title.production_year = 1986 AND person_info.note >= 'mcktusk@earlink.net'
SELECT name.name_pcode_cf, aka_name.name, MIN(aka_name.md5sum) FROM aka_name, name WHERE name.id <> 2339042 AND aka_name.imdb_index <> 'III' AND aka_name.name <= 'Snow, Susan' AND name.name_pcode_nf = 'B6163' AND name.name_pcode_cf = 'S5634' GROUP BY name.name_pcode_cf, aka_name.name ORDER BY name.name_pcode_cf ASC
SELECT person_info.info, info_type.info, name.name_pcode_nf, movie_info_idx.info, cast_info.person_id FROM movie_info_idx JOIN info_type ON info_type.id = movie_info_idx.info_type_id JOIN person_info ON person_info.info_type_id = info_type.id JOIN name ON name.id = person_info.person_id JOIN cast_info ON cast_info.person_id = name.id WHERE name.md5sum <= 'db5ceb54b692bd2ceeba0a7f970bdd98' AND name.surname_pcode >= 'T62' AND movie_info_idx.info < '0001221000' ORDER BY movie_info_idx.info ASC
SELECT cast_info.id, comp_cast_type.kind, title.title, char_name.md5sum, complete_cast.status_id FROM comp_cast_type JOIN complete_cast ON complete_cast.status_id = comp_cast_type.id JOIN title ON title.id = complete_cast.movie_id JOIN cast_info ON cast_info.movie_id = title.id JOIN char_name ON char_name.id = cast_info.person_role_id WHERE char_name.name > 'Himself, Disc Jockey' AND title.id >= 967357 ORDER BY char_name.md5sum DESC, cast_info.id DESC
SELECT MIN(k.keyword) AS movie_keyword, MIN(n.name) AS actor_name, MIN(t.title) AS hero_movie FROM cast_info AS ci, keyword AS k, movie_keyword AS mk, name AS n, title AS t WHERE k.keyword IN ('superhero', 'sequel', 'second-part', 'marvel-comics', 'based-on-comic', 'tv-special', 'fight', 'violence') AND n.name LIKE '%Downey%Robert%' AND t.production_year > 2014 AND k.id = mk.keyword_id AND t.id = mk.movie_id AND t.id = ci.movie_id AND ci.movie_id = mk.movie_id AND n.id = ci.person_id
SELECT movie_keyword.id, keyword.id FROM movie_keyword JOIN keyword ON keyword.id = movie_keyword.keyword_id WHERE keyword.id < 22473 AND movie_keyword.id < 1402415 AND keyword.phonetic_code = 'C4265' AND movie_keyword.keyword_id <= 6931
select title.title, title.series_years, title.md5sum, title.id, sum(title.episode_of_id) from comp_cast_type JOIN complete_cast ON complete_cast.status_id = comp_cast_type.id JOIN title ON title.id = complete_cast.movie_id JOIN movie_info ON movie_info.movie_id = title.id where title.phonetic_code >= 'J5' AND movie_info.movie_id <= 2342737 AND title.md5sum < '6feeed89f6a89b5e9c266b5394c332be' group by title.title, title.series_years, title.md5sum, title.id
select movie_keyword.movie_id, title.series_years, title.episode_nr from cast_info JOIN title ON title.id = cast_info.movie_id JOIN movie_keyword ON movie_keyword.movie_id = title.id where cast_info.movie_id = 2019341 AND cast_info.id <= 33305784 AND cast_info.role_id = 9 order by movie_keyword.movie_id DESC
SELECT movie_info.info, info_type.info, COUNT(info_type.id) FROM info_type JOIN movie_info ON movie_info.info_type_id = info_type.id WHERE movie_info.info_type_id <> 43 AND movie_info.id >= 12231308 AND movie_info.movie_id >= 1096319 AND info_type.info <= 'death date' GROUP BY movie_info.info, info_type.info HAVING COUNT(info_type.id) < 8 ORDER BY COUNT(info_type.id) DESC
select title.season_nr, title.title, link_type.id, movie_companies.company_type_id, max(title.episode_of_id) from link_type JOIN movie_link ON movie_link.link_type_id = link_type.id JOIN title ON title.id = movie_link.movie_id JOIN movie_companies ON movie_companies.movie_id = title.id where movie_link.id > 23398 AND movie_companies.note > '(1914) (USA) (theatrical)' group by title.season_nr, link_type.id, title.title, movie_companies.company_type_id order by title.title DESC, title.season_nr DESC, movie_companies.company_type_id ASC
select cast_info.id, name.md5sum, aka_name.person_id, role_type.id from aka_name JOIN name ON name.id = aka_name.person_id JOIN cast_info ON cast_info.person_id = name.id JOIN role_type ON role_type.id = cast_info.role_id where cast_info.nr_order = 27 AND cast_info.note > '(promo producer)' AND cast_info.person_role_id <= 1978810 AND role_type.id >= 9
SELECT person_info.info, name.name_pcode_nf FROM person_info, name WHERE name.name_pcode_nf < 'M2454' AND name.gender <> 'm' AND person_info.person_id >= 1718960 AND person_info.note = 'MilleniumBabyGirl' AND name.id = 1303966 AND name.surname_pcode >= 'C5' AND name.md5sum = 'dc464defcd75723260c6fe0100380030' AND name.name_pcode_cf < 'E6256' ORDER BY person_info.info DESC
select title.episode_of_id, movie_info.info_type_id, title.production_year, max(movie_info.note) from movie_link JOIN title ON title.id = movie_link.movie_id JOIN movie_info ON movie_info.movie_id = title.id where movie_info.movie_id < 1707956 AND movie_info.info > 'USA:2012' AND title.series_years >= '2009-????' group by title.episode_of_id, movie_info.info_type_id, title.production_year having max(movie_info.note) >= 'Erik Urtz'
